CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT UNIQUE, password_hash TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles (user_id INTEGER NOT NULL REFERENCES users(id), role_id INTEGER NOT NULL REFERENCES roles(id), PRIMARY KEY (user_id, role_id));
CREATE TABLE IF NOT EXISTS employees (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), job_title TEXT, hired_at TEXT, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT UNIQUE, email TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vehicle_types (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS vehicle_makes (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS vehicle_models (id INTEGER PRIMARY KEY, make_id INTEGER REFERENCES vehicle_makes(id), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_vehicles (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), type_id INTEGER REFERENCES vehicle_types(id), model_id INTEGER REFERENCES vehicle_models(id), plate_number TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS parking_lots (id INTEGER PRIMARY KEY, name TEXT NOT NULL, address TEXT, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS parking_zones (id INTEGER PRIMARY KEY, lot_id INTEGER NOT NULL REFERENCES parking_lots(id), name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS parking_spots (id INTEGER PRIMARY KEY, zone_id INTEGER NOT NULL REFERENCES parking_zones(id), label TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'available');
CREATE TABLE IF NOT EXISTS cameras (id INTEGER PRIMARY KEY, lot_id INTEGER REFERENCES parking_lots(id), name TEXT NOT NULL, location TEXT, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS barriers (id INTEGER PRIMARY KEY, lot_id INTEGER REFERENCES parking_lots(id), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'closed');
CREATE TABLE IF NOT EXISTS plate_detections (id INTEGER PRIMARY KEY, camera_id INTEGER REFERENCES cameras(id), plate_number TEXT NOT NULL, confidence REAL, image_path TEXT, crop_path TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parking_sessions (id INTEGER PRIMARY KEY, vehicle_id INTEGER REFERENCES customer_vehicles(id), spot_id INTEGER REFERENCES parking_spots(id), detection_id INTEGER REFERENCES plate_detections(id), plate_number TEXT NOT NULL, entry_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, exit_at TEXT, fee_amount NUMERIC NOT NULL DEFAULT 30, status TEXT NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS access_logs (id INTEGER PRIMARY KEY, barrier_id INTEGER REFERENCES barriers(id), detection_id INTEGER REFERENCES plate_detections(id), action TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rate_plans (id INTEGER PRIMARY KEY, name TEXT NOT NULL, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS rate_rules (id INTEGER PRIMARY KEY, plan_id INTEGER NOT NULL REFERENCES rate_plans(id), vehicle_type_id INTEGER REFERENCES vehicle_types(id), hourly_rate NUMERIC NOT NULL DEFAULT 30);
CREATE TABLE IF NOT EXISTS tariffs (id INTEGER PRIMARY KEY, name TEXT NOT NULL, rate NUMERIC NOT NULL, starts_at TEXT, ends_at TEXT);
CREATE TABLE IF NOT EXISTS reservations (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), lot_id INTEGER NOT NULL REFERENCES parking_lots(id), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'booked');
CREATE TABLE IF NOT EXISTS reservation_spots (reservation_id INTEGER NOT NULL REFERENCES reservations(id), spot_id INTEGER NOT NULL REFERENCES parking_spots(id), PRIMARY KEY (reservation_id, spot_id));
CREATE TABLE IF NOT EXISTS invoices (id INTEGER PRIMARY KEY, customer_id INTEGER REFERENCES customers(id), session_id INTEGER REFERENCES parking_sessions(id), subtotal NUMERIC NOT NULL DEFAULT 0, tax_amount NUMERIC NOT NULL DEFAULT 0, total NUMERIC NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoice_items (id INTEGER PRIMARY KEY, invoice_id INTEGER NOT NULL REFERENCES invoices(id), description TEXT NOT NULL, quantity NUMERIC NOT NULL DEFAULT 1, unit_price NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS payment_methods (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY, invoice_id INTEGER REFERENCES invoices(id), method_id INTEGER REFERENCES payment_methods(id), amount NUMERIC NOT NULL, status TEXT NOT NULL DEFAULT 'paid', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS refunds (id INTEGER PRIMARY KEY, payment_id INTEGER NOT NULL REFERENCES payments(id), amount NUMERIC NOT NULL, reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cash_registers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, opening_balance NUMERIC NOT NULL DEFAULT 0, is_open INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS shifts (id INTEGER PRIMARY KEY, employee_id INTEGER REFERENCES employees(id), register_id INTEGER REFERENCES cash_registers(id), opened_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, closed_at TEXT, closing_balance NUMERIC);
CREATE TABLE IF NOT EXISTS product_categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY, category_id INTEGER REFERENCES product_categories(id), name TEXT NOT NULL, sku TEXT NOT NULL UNIQUE, price NUMERIC NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS inventory_levels (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL UNIQUE REFERENCES products(id), quantity_on_hand INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY, name TEXT NOT NULL, phone TEXT, email TEXT);
CREATE TABLE IF NOT EXISTS purchase_orders (id INTEGER PRIMARY KEY, supplier_id INTEGER REFERENCES suppliers(id), status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS purchase_order_items (id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES purchase_orders(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL, unit_cost NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements (id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), change_amount INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS taxes (id INTEGER PRIMARY KEY, name TEXT NOT NULL, rate NUMERIC NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS coupons (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, discount_percent NUMERIC NOT NULL DEFAULT 0, is_active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS customer_coupons (customer_id INTEGER NOT NULL REFERENCES customers(id), coupon_id INTEGER NOT NULL REFERENCES coupons(id), used_at TEXT, PRIMARY KEY (customer_id, coupon_id));
CREATE TABLE IF NOT EXISTS sales (id INTEGER PRIMARY KEY, reference TEXT NOT NULL UNIQUE, customer_id INTEGER REFERENCES customers(id), shift_id INTEGER REFERENCES shifts(id), payment_method_id INTEGER REFERENCES payment_methods(id), subtotal NUMERIC NOT NULL, tax_amount NUMERIC NOT NULL DEFAULT 0, total NUMERIC NOT NULL, status TEXT NOT NULL DEFAULT 'paid', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sale_items (id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL, unit_price NUMERIC NOT NULL, line_total NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY, category_id INTEGER REFERENCES expense_categories(id), description TEXT NOT NULL, amount NUMERIC NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS expense_categories (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), message TEXT NOT NULL, is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, value TEXT);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY, user_id INTEGER REFERENCES users(id), action TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS daily_summaries (id INTEGER PRIMARY KEY, summary_date TEXT NOT NULL UNIQUE, vehicle_count INTEGER NOT NULL DEFAULT 0, sales_total NUMERIC NOT NULL DEFAULT 0, parking_total NUMERIC NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS loyalty_accounts (id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL UNIQUE REFERENCES customers(id), points INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS loyalty_transactions (id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES loyalty_accounts(id), points INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_events (id INTEGER PRIMARY KEY, event_type TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX IF NOT EXISTS ix_sessions_entry_at ON parking_sessions(entry_at);
CREATE INDEX IF NOT EXISTS ix_sessions_plate ON parking_sessions(plate_number);
CREATE INDEX IF NOT EXISTS ix_sales_created_at ON sales(created_at);
CREATE INDEX IF NOT EXISTS ix_detections_created_at ON plate_detections(created_at);
